/**
 * The help center's content model.
 *
 * Every screen ("mask") in TREK registers a help context; a context owns a set
 * of guides. The words live in the i18n catalogue under `help.ctx.<id>.*` and
 * `help.guide.<id>.*`, the pictures and walkthroughs under
 * `public/help-media/`, generated by the Playwright run in `e2e/help/` from
 * the same guide definitions. Nothing here is prose: this file only says what
 * exists, so a guide that is registered but has no text or no picture fails a
 * test instead of rendering a raw key.
 */

/** How much of a task a guide covers; drives the chip and the media it carries. */
export type HelpGuideSize = 'quick' | 'guide' | 'tour'

export interface HelpDocLink {
  /** Wiki slug, e.g. `Creating-a-Trip`. */
  slug: string
  /** GitHub-style heading anchor inside that page, without the `#`. */
  anchor?: string
}

export interface HelpGuideMedia {
  /** One focus shot per step, `step-<n>.webp`. */
  steps: boolean
  /** The state after the last step, `result.webp`. */
  result: boolean
}

/** Icon names the help components know how to draw (see components/Help/helpIcons.ts). */
