export interface HelpGuide {
  id: string
  /** The context the guide belongs to; a guide may be reached from others via `related`. */
  context: string
  icon: HelpIcon
  size: HelpGuideSize
  /** Number of steps; the texts are `help.guide.<id>.step.1` … `.step.<steps>`. */
  steps: number
  /** Number of "good to know" notes; `help.guide.<id>.tip.1` … */
  tips: number
  media: HelpGuideMedia
  /** Where the reference documentation continues. */
  docs?: HelpDocLink
  /** An in-app route the guide can take the reader to; label is `help.guide.<id>.link`. */
  link?: string
  related?: string[]
}

export interface HelpContext {
  id: string
  icon: HelpIcon
  /**
   * The screen this one lives under, for the screen switcher: a journal is
   * reached from the Journey list, a settings tab from Settings. Top-level
   * screens have none.
   */
  parent?: string
  /**
   * Where the screen is in the app, for the "go there" button. Screens that
   * need an id in the address (a journal, the studio) have none.
   */
  route?: string
  /** Number of "on this screen" bullets; `help.ctx.<id>.bullet.1` … */
  bullets: number
  /** Guide ids in display order. */
  guides: string[]
  /** Reference pages for the "in the docs" list. */
  docs: HelpDocLink[]
  /** Whether `help-media/ctx/<id>.webp` exists. */
  hero: boolean
}
